import { CaseOrchestrator } from '../../../src/application/cases/orchestrator';
import { MemoryCaseRepository } from '../../../src/adapters/persistence/memory-case-repository';
import { createAIAdapters } from '../../../src/adapters/ai';
import { cases, scenarios } from '../../../src/fixtures';
import { demoBundle, configBundleRef } from '../../../src/config';
import type { CaseEvent, CaseSnapshot, CaseView, ConfigBundle, Result } from '../../../src/contracts';

export function makeCase() {
  const ai = createAIAdapters({ AI_MODE: 'replay' });
  if (!ai.ok) throw new Error(ai.error.message);
  let config: ConfigBundle = structuredClone(demoBundle);
  const seed: CaseSnapshot = { caseId: 'laura', revision: 0, messages: structuredClone(cases[0].messages), assertions: [], knowledge: { facts: [] }, goal: { id: 'goal', description: 'Orientación comercial', status: 'active' }, workflowProgress: { workflowId: config.workflow.id, workflowVersion: config.workflow.version, milestones: [] }, blockers: [], proposals: [], drafts: [], events: [], decisions: [], configBundleRef: structuredClone(configBundleRef), status: 'NEEDS_ADVISOR' };
  const orchestrator = new CaseOrchestrator({ repository: new MemoryCaseRepository([seed]), ...ai.value, getConfig: () => config });
  const setR10 = (enabled: boolean) => { config = structuredClone(config); config.businessPolicy.advisoryCall.requireSpecificMoveMonthBeforeCall = enabled; config.businessPolicy.version = enabled ? 'demo-r10-on' : 'demo-r10-off'; config.workflow.businessPolicyVersion = config.businessPolicy.version; };
  return { orchestrator, setR10 };
}
export function unwrap(result: Result<CaseView>): CaseView { if (!result.ok) throw new Error(`${result.error.code}: ${result.error.message}`); return result.value; }
export function analysis(revision = 0): CaseEvent { return { eventId: `analysis-${revision}`, caseId: 'laura', actor: 'advisor', occurredAt: '2026-05-03T10:00:00Z', expectedRevision: revision, type: 'CASE_ANALYSIS_REQUESTED', payload: {} }; }
export function customerMessage(scenarioId: string, revision: number): CaseEvent {
  const message = scenarios.find(s => s.id === scenarioId)?.additions[0];
  if (!message) throw new Error(`Missing fixture ${scenarioId}`);
  return { eventId: `event-${scenarioId}`, caseId: 'laura', actor: 'customer', occurredAt: message.occurredAt, expectedRevision: revision, simulated: true, type: 'MESSAGE_RECEIVED', payload: { message: structuredClone(message) } };
}
export const fact = (view: CaseView, id: string) => view.snapshot.knowledge.facts.find(f => f.fieldId === id);
export const milestone = (view: CaseView, id: string) => view.snapshot.workflowProgress.milestones.find(m => m.milestoneId === id);
import { CaseEventSchema, CaseSnapshotSchema, type ApplicationError, type CaseEvent, type CaseRepository, type CaseSnapshot, type EventAppendResult, type EventReceipt, type Result } from '../../contracts';
import { stableSerialize } from './event-fingerprint';

const fail = (code: ApplicationError['code'], message: string, currentRevision?: number): Result<never> => ({
  ok: false, error: { code, message, retryable: code === 'REVISION_CONFLICT', ...(currentRevision === undefined ? {} : { currentRevision }) },
});
const copy = <T>(value: T): T => structuredClone(value);

/** Local, single-process storage; it is reset on process restart. */
export class MemoryCaseRepository implements CaseRepository {
  private readonly originals = new Map<string, CaseSnapshot>();
  private readonly snapshots = new Map<string, CaseSnapshot>();
  private readonly receipts = new Map<string, { fingerprint: string; receipt: EventReceipt }>();

  constructor(fixtures: CaseSnapshot[]) {
    for (const fixture of fixtures) {
      const parsed = CaseSnapshotSchema.parse(fixture);
      if (this.originals.has(parsed.caseId)) throw new Error('Duplicate case fixture');
      this.originals.set(parsed.caseId, copy(parsed));
      this.snapshots.set(parsed.caseId, copy(parsed));
    }
  }

  async get(caseId: string): Promise<Result<CaseSnapshot>> {
    const snapshot = this.snapshots.get(caseId);
    return snapshot ? { ok: true, value: copy(snapshot) } : fail('NOT_FOUND', 'Caso no encontrado');
  }

  async saveIfRevision(snapshot: CaseSnapshot, expectedRevision: number): Promise<Result<CaseSnapshot>> {
    const parsed = CaseSnapshotSchema.safeParse(snapshot);
    if (!parsed.success || !Number.isInteger(expectedRevision) || expectedRevision < 0 || parsed.data.revision !== expectedRevision + 1) return fail('INVALID_INPUT', 'Revisión o expediente inválido');
    const current = this.snapshots.get(parsed.data.caseId);
    if (!current) return fail('NOT_FOUND', 'Caso no encontrado');
    if (current.revision !== expectedRevision) return fail('REVISION_CONFLICT', 'El caso ha cambiado', current.revision);
    this.snapshots.set(parsed.data.caseId, copy(parsed.data));
    return { ok: true, value: copy(parsed.data) };
  }

  async appendEvent(event: CaseEvent): Promise<Result<EventAppendResult>> {
    const parsed = CaseEventSchema.safeParse(event);
    if (!parsed.success || parsed.data.type !== 'MESSAGE_RECEIVED') return fail('INVALID_INPUT', 'Solo se reciben mensajes por esta operación');
    const nextEvent = parsed.data;
    const fingerprint = stableSerialize(nextEvent);
    const existing = this.receipts.get(nextEvent.eventId);
    if (existing) return existing.fingerprint === fingerprint ? { ok: true, value: { receipt: copy(existing.receipt), duplicate: true } } : fail('IDEMPOTENCY_CONFLICT', 'El identificador del evento ya existe');
import type { CaseSnapshot, ConfigBundle, DecisionRecord, Result } from '../../contracts';
import { reconcileFacts } from '../../domain/facts';
import { evaluatePolicy } from '../../domain/policies/evaluate-policy';
import { evaluateWorkflow } from '../../domain/workflows/evaluate-workflow';
import { planAction } from '../../domain/actions/plan-action';
import { bundleRef } from './helpers';

export function evaluate(snapshot: CaseSnapshot, config: ConfigBundle, eventId: string, mode: 'replay' | 'openai'): Result<{ snapshot: CaseSnapshot; decision: ReturnType<typeof evaluatePolicy> }> {
  const facts = reconcileFacts({ assertions: snapshot.assertions, messages: snapshot.messages, factSchema: config.factSchema });
  if (!facts.ok) return facts;
  const context = { knowledge: facts.value, events: snapshot.events, blockers: snapshot.blockers, policyOptions: config.businessPolicy.advisoryCall };
  const decision = evaluatePolicy({ ...context, policy: config.businessPolicy, actionCatalog: config.actionCatalog });
  // The current action can be WAIT after agreement while the prior orientation
  // remains satisfied. Re-evaluate that orientation against current facts and
  // protections; never infer readiness solely from the confirmation event.
  const priorReady = config.workflow.milestones.some(m => m.terminalRoute && m.prerequisites.length > 0 && m.prerequisites.every(id => snapshot.workflowProgress.milestones.some(previous => previous.milestoneId === id && previous.status === 'completed')));
  const orientation = decision.result === 'WAIT' && decision.ruleIds.includes('R08') && priorReady
    ? evaluatePolicy({ ...context, events: context.events.filter(e => !['CUSTOMER_CONFIRMED_NEXT_STEP', 'HUMAN_HANDOFF_CONFIRMED', 'DRAFT_APPROVED', 'DRAFT_EDITED', 'DRAFT_DISCARDED', 'MESSAGE_SIMULATED_AS_SENT'].includes(e.type)), policy: config.businessPolicy, actionCatalog: config.actionCatalog })
    : decision;
  const workflow = evaluateWorkflow({ ...context, policyDecision: orientation, definition: config.workflow });
  const ref = bundleRef(config);
  const revision = snapshot.revision + 1;
  const proposal = planAction({ decision, catalog: config.actionCatalog, profile: config.agentProfile, proposalId: `proposal-${eventId}`, caseRevision: revision, configBundleRef: ref });
  if (!proposal.ok) return proposal;
  const record: DecisionRecord = { decisionId: `decision-${eventId}`, inputEventIds: [eventId], beforeRevision: snapshot.revision, afterRevision: revision, factAssertionIds: snapshot.assertions.map(a => a.assertionId), evidenceRefs: decision.evidenceRefs, ruleIds: decision.ruleIds, configBundleRef: ref, aiMode: mode, outcome: decision.result, warnings: [] };
  const terminalCompleted = config.workflow.milestones.some(m => m.terminalRoute && workflow.milestones.some(result => result.milestoneId === m.id && result.status === 'completed'));
  const status: CaseSnapshot['status'] = decision.result === 'STOP_CONTACT' ? 'DO_NOT_CONTACT' : terminalCompleted ? 'NEXT_STEP_AGREED' : decision.result === 'HUMAN_REVIEW_REQUIRED' ? 'ON_HOLD_REVIEW' : decision.result === 'WAIT' ? 'WAITING_CUSTOMER' : 'NEEDS_ADVISOR';
  return { ok: true, value: { snapshot: { ...snapshot, revision, assertions: snapshot.assertions, knowledge: facts.value, workflowProgress: workflow, proposals: [...snapshot.proposals.map(p => ({ ...p, status: 'superseded' as const })), proposal.value], decisions: [...snapshot.decisions, record], configBundleRef: ref, status, analysisStatus: 'complete' }, decision } };
}

