import { it } from 'vitest';
import { cases } from '../src/fixtures';
import { demoBundle, configBundleRef } from '../src/config';
import { openAITransport, OpenAIInterpreter, OpenAIDraftGenerator } from '../src/adapters/ai/openai';
import { CaseOrchestrator } from '../src/application/cases/orchestrator';
import { MemoryCaseRepository } from '../src/adapters/persistence/memory-case-repository';
import type { CaseSnapshot } from '../src/contracts';
it('live synthetic scenarios', async () => {
 let count=0;
 const specs = [ ['L1','laura',''],['L2','laura',''],['J1','javier',''],['J2','javier',''],['R1','rosa',''],['R2','rosa',''],['L3','laura','Me corrijo: lo que comenté era en bruto.'],['J3','javier','¿Quién se hace responsable si algo falla? Me preocupa dar mis datos.'],['R3','rosa','¿Me podéis asegurar por escrito que la operación ya está concedida?'] ];
 await Promise.all(specs.map(async ([tag,id,addition]) => {
  const c=cases.find(x=>x.caseId===id)!;
  const seed: CaseSnapshot={caseId:id, revision:0,messages:structuredClone(c.messages),assertions:[],knowledge:{facts:[]},goal:{id:'goal',description:'Orientación',status:'active'},workflowProgress:{workflowId:demoBundle.workflow.id,workflowVersion:demoBundle.workflow.version,milestones:[]},blockers:[],proposals:[],drafts:[],events:[],decisions:[],configBundleRef,status:'NEEDS_ADVISOR'};
  if(addition) seed.messages.push({messageId:'variation',conversationId:seed.messages[0].conversationId,role:'customer',occurredAt:'2026-05-03T09:00:00Z',content:{type:'text',text:addition},simulated:true});
  const transport=openAITransport(process.env.OPENAI_API_KEY!,process.env.OPENAI_MODEL!,25000);
  const wrapped={complete:async (...args:Parameters<typeof transport.complete>)=>{ const n=++count; if(n>20) throw Error('budget'); const t=Date.now(); try {const out=await transport.complete(...args);console.log('REQUEST',JSON.stringify({n,tag,kind:args[2],ms:Date.now()-t,out}));return out;}catch(e){console.log('REQUEST_ERROR',JSON.stringify({n,tag,kind:args[2],ms:Date.now()-t,error:e instanceof Error?e.message:'unknown'}));throw e;} }};
  const o=new CaseOrchestrator({repository:new MemoryCaseRepository([seed]),interpreter:new OpenAIInterpreter(wrapped),draftGenerator:new OpenAIDraftGenerator(wrapped),mode:'openai',getConfig:()=>demoBundle});
  const result=await o.handleEvent({eventId:'analysis',caseId:id,actor:'advisor',occurredAt:'2026-05-03T10:00:00Z',expectedRevision:0,type:'CASE_ANALYSIS_REQUESTED',payload:{}});
  console.log('RESULT',JSON.stringify({tag,result}));
 }));
},120000);
